from pathlib import Path
from zipfile import ZipFile
from xml.etree import ElementTree as E
from datetime import datetime
import json

ROOT=Path(r'E:\shengtu\skills-v2.7-development-snapshot-20260814')
WORK=ROOT/'work/gushu_20260907'
SRC=Path(r'E:\shengtu\多门课版式\4-4 弹词类-图片素材导出\4-3鼓书类.docx')
NS={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
with ZipFile(SRC) as z:
    tree=E.fromstring(z.read('word/document.xml'))
    paras=[''.join(x.text or '' for x in p.findall('.//w:t',NS)) for p in tree.findall('.//w:body//w:p',NS)]
    assert len(paras)==18 and all(paras)
    assert not tree.findall('.//w:drawing',NS)
TEXT=WORK/'4-3鼓书类_逐段原文.txt'
TEXT.write_text('\n'.join(paras)+'\n',encoding='utf-8')
assets=json.loads((WORK/'reference_inventory.json').read_text(encoding='utf-8'))
refs={a['id']:a for a in assets}
def span(line,begin=None,end_before=None):
    t=paras[line-1]
    a=t.index(begin) if begin else 0
    b=t.index(end_before) if end_before else len(t)
    assert a<b
    s=t[a:b]
    return dict(source_id='source-1',line=line,start_char=a+1,end_char=b,start_text=s[:16],end_text=s[-16:])
def full(n): return span(n)
pages=[]
def add(title,spans,goal,relation,words,image_task,forbid,refids,capacity,bridge):
    p=dict(page_id=f'GS-A{len(pages)+1:02}',order=len(pages)+1,title=title,owned_spans=spans,context_refs=[],teaching_goal=goal,teaching_relation=relation,must_show_items=words.split('|'),image_pedagogical_task=image_task,forbidden_semantic_drift=forbid,refids=refids.split(),capacity=capacity,bridge=bridge)
    pages.append(p)

add('鼓书类的概念与四个关键要素',[full(3)],'能依据伴奏、表演、题材和地域四方面辨认鼓书类。','鼓为主要伴奏、说唱故事、通俗题材和地域差异共同限定类别，不是四个先后步骤。','鼓|板类乐器|说唱故事|当地方言|说唱结合|说交代情节、刻画人物|唱抒发情感、渲染气氛|民间传说|语言通俗|无统一唱腔和表演模式','将鼓的核心地位与其他限定条件联系起来。','不能将弹拨乐器设为核心；不能把四要素表现成发展时间线。','R25','R25实图容纳中心器物和四项短说明；本页四个限定维度与其文字负荷接近，需替换为鼓书语义。定义的口播全文不重复铺满画面。','定义先于实例；本页只界定要素，第7—12页再解释机制与差异。')
add('鼓书实例与鼓词概念边界',[full(4)],'能把实例归入鼓书，并按原稿辨明鼓词与鼓书类关系。','街巷表演、《杨家将》以及南北曲种是实例；鼓词包含鼓书类是原稿另一个上位—分支关系，不能以南北差异替代包含关系。','背鼓、拿竹板|《杨家将》|京韵大鼓|温州鼓词|鼓词是曲艺形式总称|鼓书类是其代表性分支|更突出“鼓”的伴奏作用','清楚区分概念边界和边界内的实例，示意而非伪造影视截图。','原稿的包含方向不可反转；不移植参考图中的“弹词类与鼓书类”并列关系。','R25 R04','四项实例可用短名归组，核心关系只有一个上位词与一个分支。R25支持少量标签围绕核心对象、R04支持清晰关系提示，但未直接证明嵌套关系的具体版式；B需保留该实现开放项。','与第1页合并会让定义、实例和术语包含三层任务争用说明空间，故独立一页。')
add('唐宋说唱艺术与鼓书渊源',[full(5)],'理解唐宋说唱形式为鼓书提供的不同基础。','唐代变文提供说唱结合框架，宋代陶真演唱民间故事形成雏形；货郎儿仅按原稿列为渊源，不能补造其细节。','唐代变文|宋代“陶真”“货郎儿”|宗教说唱形式|有说有唱|“说唱结合”框架|盲人艺人|琵琶或鼓|民间故事|鼓书类雏形','追踪两段历史中的形式贡献和伴奏变化。','不能把唐宋画成现代鼓书已经定型；不能给货郎儿虚构年代或乐器。','R07','R07支持分阶段短文与示意图并置；本页只有唐、宋两阶段，保留宋代乐器的“或”而非必须同时使用。','先讲渊源，再讲明清成熟；不与第4页混成含分支和阶段的拥挤通史。')
add('明代鼓词名称与清初两种演唱方式',[span(6,end_before='鸦片战争后')],'区分清初北方鼓词两种演唱方式及其流行环境。','明代出现名称、清初演唱兴盛是时间背景；自击鼓板与自弹三弦是同一时期的两种方式，不是必然演化的前后阶段。','明代有“鼓词”名称|演唱记载少|清代初年|自击鼓板无伴奏|流行农村|中篇鼓书|曲调朴拙|自弹三弦说唱|农村和城市|诗赞体和乐曲体','对照表演动作、场所和曲词差异，避免将两条方式连成因果链。','“无伴奏”须和“自击鼓板”一起按原稿保留，不能误示完全没有乐器；不把两方式设为所有鼓书的永久分类。','R04 R29','R29容纳两对象各三项短说明，R04可清楚并列分工；本页两方式各有动作、环境、曲词信息，明清背景仅作简短时间上下文。','“鸦片战争后”改讲拼档与近代改造，另页接续可保住本页两方式的同屏辨别。')
add('近代大鼓书的形成与民国发展',[span(6,begin='鸦片战争后'),span(7,end_before='新中国成立后')],'理解拼档、艺人加工和专业化发展在两个时期的不同作用。','鸦片战争后拼档形成近代大鼓书并加工出品种；民国时期专业队伍、场所与京剧技巧推动进一步发展。','鸦片战争后|拼档演出|近代大鼓书|西河大鼓|民国时期|专业艺人队伍|固定表演场所|京剧表演技巧|京韵大鼓','按时间辨认形成与发展的不同机制。','不得画成西河大鼓演变成京韵大鼓；不把民国技巧吸收误归鸦片战争后同一节点。','R07','R07三个时间节点的实例提供分阶段承载依据，本页两个阶段可分别放入机制短语与例名；不再加入新中国和当代节点。','跨原段合并是为了连接近代形成与专业化，切开原第7段不改变句子或时序。')
add('新中国成立后的创新与当代传承',[span(7,begin='新中国成立后')],'认识传统曲目整理、新作与非遗保护如何接续。','政府扶持、传统整理和新曲目创作属于新中国成立后的发展；当代非遗保护承接其传承价值。','新中国成立后|政府扶持|整理改编传统曲目|创作新曲目|新时代生活|京韵大鼓、温州鼓词|国家级非物质文化遗产名录|保护和传承','区别曲目实践与保护行动，表现接续而非等同。','不添加批准文号、证书、入选年份或虚构官方牌匾；“了解起源和发展后，”只作过渡口播。','R07','R07已呈现新中国、当代两节点及短说明；本页删除其不属于鼓书原稿的人物和器物语义，仅利用阶段信息可读性的证据。','与第5页合并将成为四阶段且每阶段含多机制；拆开保留保护与创新的明确区别。')
add('以鼓为核心的伴奏系统',[full(8),full(9)],'辨别鼓、板和部分弦乐器的作用及三种实例组合。','鼓控制节奏和气氛，板辅助节奏，部分曲种增加弦乐器；三种曲种组合是这一原则的不同实现。','鼓|板类乐器|部分曲种加入弦乐器|节奏控制核心|不同部位和力度|西河大鼓|鼓、竹板和三弦|南阳鼓词|扁圆小鼓和犁铧钢片|京韵大鼓|弦乐器','把每个曲种与正确乐器组合对应，并突出鼓板功能。','不能省去“部分”而把三弦推广为全部曲种必备；真实器物形制未有获核实照片，不将示意称实物证据。','R02','R02支持三组器物和各组短标注。当前三组名称与组合可同屏比较，鼓板功能用总说明承担，不另塞三套完整乐器介绍。犁铧钢片形制仍须B处理真实素材或示意边界。','第8段导语并入，不单造一页四特征目录；第1页要素在此深化为功能与实例。')
add('说与唱的分工和配合',[full(10)],'理解说负责叙事、唱突出抒情，并识别不同曲种权重。','说用白话方言交代背景，唱抒发情感渲染气氛；温州鼓词与京东大鼓体现配合方式差异。','说唱结合|白话、方言|交代故事背景|“唱”是核心|抒发情感、渲染气氛|民间小调|温州鼓词以唱为主|京东大鼓说唱结合灵活','将说唱作用同屏辨认，不用无关演员照片代替分工解释。','不得由双侧等宽参考推导说唱比重相等；不得加入参考中的“旋律优美”作为本稿必显结论。','R04','R04直接展示说唱两端的作用和共同关系；本页文字负荷是两端作用加两条曲种例证，可用短语承载，不必拆开而割裂配合。','上一页是乐器机制，本页是表演机制，不能为了相邻合并而削弱两套对照。')
add('题材与民间价值的对应',[full(11)],'能把作品与其歌颂的价值对应起来。','贴近民间生活是共同背景，《呼家将》《高机与吴三春》《杨家将》分别对应忠诚正直、爱情和反抗精神、爱国情怀；新生活和讽刺作品补充题材广度。','民俗性和教化性|山东大鼓《呼家将》|忠诚正直|温州鼓词《高机与吴三春》|爱情和反抗精神|安徽大鼓《杨家将》|爱国情怀|新时代生活|滑稽讽刺','保持曲种—作品—价值的逐项对应，让例子承担解释任务。','作品人物不能作为历史表演实录；不能把爱情和反抗拆成互斥题材；不把原稿所有作品只归忠君故事。','R14','R14展示四部作品的名称、题材和一句说明；当前三组曲种—作品—价值名称稍长，少一组且不扩写剧情，附加题材仅列短词，具备静态承载依据。','原第11段是一套完整映射，拆成每部作品一页会重复共同结论。')
add('地域差异的来源与北方风格',[span(12,end_before='西河大鼓流行于')],'理解地域差异来自方言、音乐、民俗，而不是唯一的南北刻板二分。','地域条件形成多样风格；北方高亢明快是概括，京韵大鼓刚柔相济是具体实例。','方言、音乐、民俗|北方方言|高亢激昂|节奏明快|京韵大鼓|北京方言|刚柔相济|雅俗共赏','先把地域条件联系到风格，再区分概括与具体实例。','不能把北方一律画成粗犷吼唱；“雅俗共赏”原稿断句不擅改正文，屏显只保留该词。','R25 R16','R25支持若干条件说明，R16支持曲种少量属性。此页只承载地域原因及一个例子，不把后续西河两类书目和南方两例一并堆入。','后两页保持同属第四特征的连续标识；不把地域分析重复升级为三段新的代表曲种详解。')
add('西河大鼓的大书与小书',[span(12,begin='西河大鼓流行于',end_before='南方鼓书用')],'能从说唱权重和故事长度区分大书、小书。','西河大鼓内部的大书与小书对应不同说唱配比和故事类型，是同曲种内部对照。','西河大鼓|河北、山东|流畅明快|大书|多说少唱|长篇历史故事|小书|多唱少说|短篇抒情故事','同屏对照两类，不让大、小名称被误读为音量或鼓的尺寸。','不按大小画两种鼓代替书目类别；不能把小书变成不讲故事。','R04','R04两组作用对照的文字区足以容纳大书、小书各两项区别；加入流行地区与共同唱腔仍是短标签。','与第10页合并会混合地域因果与曲种内部分类；与第12页合并会将不同层级误作南北一一对应。')
add('南方鼓书的风格与两个实例',[span(12,begin='南方鼓书用')],'识别温州鼓词与历史上扬州鼓词的南方特色。','南方方言与委婉细腻是共同描述，温州一人多件乐器与扬州鼓琴合奏是不同实例；扬州鼓词已失传是必要状态限定。','南方方言|委婉细腻|温州鼓词|温州方言|南国民歌风味|兼扮角色|扬州鼓词（已失传）|江苏扬州|鼓琴合奏|曲调温婉','对照两个实例的地域、表演与存续状态。','不得用目录中扬州弹词图冒充扬州鼓词；不得把已失传曲种制作成真实当代表演现场。','R29','R29两对象各三短说明的实例支持这里两个对象的属性展示；“已失传”必须显著可读，不使用缩小图注规避。','不再拆成一例一页：本段只有两例且共同说明南方特色，独立拆页会重复共同背景。')
add('京韵大鼓的身份与形成',[full(13),span(14,end_before='伴奏乐器有')],'认识京韵大鼓的名称、地域、非遗年份与改造来源。','河北河间木板大鼓经语音、京剧技巧唱腔和伴奏改革形成京韵大鼓；地域和非遗身份是属性，不是改革步骤。','京韵大鼓|京音大鼓|京津、华北及东北|2008 年|非遗名录|清末民初|河北河间木板大鼓|河间方言|北京语音|京剧技巧与唱腔|增加伴奏','把来源与改造内容联系到新曲种，同时保持身份属性清楚。','不可移植参考苏州评弹的2006年；原稿“源于清末民初”不扩写具体年。','R16 R07','R16提供名称、地域、非遗、定位短属性的承载证据；本页还需形成机制，因此不再并入全部乐器、句式、作品和流派。身份与形成如何整合留B，不预定格数或箭头。','第13段仅为代表曲种导语，与首例并页；接第14页解释表演和作品。')
add('京韵大鼓的表演与代表作品',[span(14,begin='伴奏乐器有')],'从表演方式、唱腔和作品认识京韵大鼓艺术特色。','书鼓板三弦与一人站唱共同构成表演方式；两部作品各表现不同情境；刘白骆是流派并列，不是作品分类。','书鼓、板、三弦|一人站唱自击鼓板|板腔体|七字句|《丑末寅初》|黎明景象|《黛玉焚稿》|林黛玉悲伤|刘派|白派|骆派','识别演唱姿态和乐器，区分两部作品的表现对象。','不能因配图便捷改为双人坐唱；不虚构各流派人物或技法；唱词“基本七字句”不是所有句都严格七字。','R29 R14','R29支持两对象少量说明，R14支持作品名与主题配对；本页两部作品之外仅有共用表演条件和流派短名，须保证“板腔体”“基本七字句”可读。未验证人物持器与乐器位置的生成准确性。','与第13页合并会同时包含身份、形成、表演、作品、流派；分两页保留两个不同学习任务。')
add('西河大鼓的源流与艺术特点',[full(15)],'把西河大鼓的地域、形成和朴实表演特点关联起来。','源于河北农村、河间大鼓经马三峰改革是历史关系；乐器配合、方言、唱腔和历史传说题材是当前特征。','河北、山东、京津|河北中部农村|河间大鼓|清末|马三峰|书鼓、竹板和三弦|鼓点和板点配合紧密|简洁朴实|平腔|河北方言|历史演义、民间传说|《杨家将》|情感表达','突出鼓板协作与地方说唱特征，源流仅作必要背景。','不重复第11页的大书小书整套正文；不把“河间大鼓”与京韵来源原词“木板大鼓”静默合并；不添加非遗年份。','R16 R02','本段作品只有一部，流派没有展开，负荷明显低于京韵全段。R16展示曲种短属性，R02展示组合标注：地域源流一组、乐器一组、唱腔方言题材短语一组可承担本段，不要求给每一条另配图。具体成图仍需校准。','保持一页而非机械复制京韵两页；第11页仅作为已讲过的背景，不重复占有源正文。')
add('温州鼓词的身份与表演特点',[span(16,end_before='曲目题材广泛')],'认识温州鼓词的地方身份、起源限定与单档表演。','唱词、瞽词、盲词是别称，2006年为原稿身份年份；相传明代祀神演唱是来源，单档多乐器兼角色是表演特征。','浙江温州及毗邻地区|唱词|瞽词|盲词|南方鼓书类代表|2006 年|相传始于明代|祀神演唱|扁鼓|单档表演|一人可敲多件乐器、兼扮角色|南国民歌风味|多个板式|南北两派','显示一人兼具多项表演任务，而非多人合奏；将名称与身份属性区分。','保留“相传”而非断言始于明代；不可因旧评弹双档图改为双人；不虚构多件乐器的具体名单。','R16 R25','R16的身份说明与R25的核心对象多属性提供静态参照，但本页别称较多，来源只保留限定短句、不增加剧情插画。作品清单和长篇演唱特性分到后页，避免文字挤压表演示意。','第12页已讲南方风格，本页深化为曲种身份与单档特征；不重复其完整旁白。')
add('温州鼓词的曲目与长篇叙事',[span(16,begin='曲目题材广泛')],'辨认三部代表作及《陈十四收妖》的长篇演唱特点。','民间传说和历史小说是题材来源，三部作品并列；陈十四学法灭妖和可连唱几昼夜仅属于《陈十四收妖》。','民间传说和历史小说|《陈十四收妖》|《高机与吴三春》|《王十朋中状元》|经典长篇曲目|陈十四学法灭妖|可连唱几昼夜','把三部作品与其中一个展开实例清楚区分，不把时长特征套给全部。','不编造后两部作品剧情；“几昼夜”不可改成精确天数；情节插图只能是故事示意。','R14','R14可容纳四部作品及短说明；当前三部只一部有展开说明，故无需每曲一页。长篇标签与情节说明共同归到陈十四，不能仿四等分而强补另两部信息。','与第16页合并会把身份、表演与三部作品压成过长简介；此处转为曲目学习。')
add('其他曲种概览与山东大鼓',[span(17,end_before='京东大鼓流行于')],'认识其他曲种的存在，并掌握山东大鼓的基本识别信息。','山东、京东、安徽、东北等是鼓书类其他曲种；本页按原序先展开山东大鼓，东北仅被点名。','山东大鼓、京东大鼓、安徽大鼓、东北大鼓|梨花大鼓|山东、河北、河南|鼓、钢板和三弦|高亢激昂|《黑驴段》|《拴娃娃》','将其他曲种的集合与山东实例分清，建立名称、乐器和作品对应。','不得给东北大鼓补造地域、乐器或作品；钢板不得偷换竹板；不误归为全部北方鼓书共同配置。','R16','R16曲种身份样例可支持别称、地域、伴奏、唱腔和作品短标签；总览四个曲种名称只作范围提示，不为东北增设假详情。','本页保留山东完整说明；若与下页合并，三曲种需同时呈现不同字段和六部作品，超出已见三乐器组短标签样例的证明范围。')
add('京东大鼓与安徽大鼓',[span(17,begin='京东大鼓流行于')],'区分两个曲种各自的地域、唱腔与代表作。','京东与安徽是同级曲种介绍；共同有地域、唱腔、作品，安徽另有原名与起源，不能为了对称补给京东。','京东大鼓|河北东部、天津、北京|简洁明快、韵味独特|《鞭打芦花》|《王二姐思夫》|安徽大鼓|安徽泗县|泗州大鼓|淮北、长江两岸|南口、北口、花口|《敌后武工队》|《夸红旗》','保持两个曲种及其作品清楚对应；容许信息量不对称。','不将两曲种串成历史演变；不给京东虚构起源和原名；不把安徽原名改为泗州戏。','R29','R29的两曲种各三条说明提供相近信息载体；本页共同字段为地域、唱腔、作品，安徽原名及起源并入其身份说明，不另铺地图或逐部剧情。小字是否可读留代表页验证。','比拆成两页更利于同级曲种辨认且不切断内部关系；与第18页合并则三套属性和六部曲目争用空间。')

