comparisons=[]
def compare(cid,indices,alternative_groups,reason):
    selected=[pages[i-1] for i in indices]
    spans=[s for p in selected for s in p['owned_spans']]
    comparisons.append(dict(comparison_id=cid,source_spans=spans,alternatives=[dict(candidate_id=cid+'-alternative',proposed_page_spans=alternative_groups,reason=reason)],selected_page_ids=[p['page_id'] for p in selected],decision_reason=reason))
def own(*nums):return [s for n in nums for s in pages[n-1]['owned_spans']]
compare('C01',[1,2],[own(1,2)],'合并会叠加定义四要素、南北实例和鼓词包含关系；保留两页，第一页面向识别条件，第二页面向应用与概念边界。')
compare('C02',[3,4,5,6],[own(3),[full(6)],[full(7)]],'按原段形成三页看似省一页，却使第6段兼顾两种演唱方式与近代拼档，第7段含三个高信息阶段。现选四页，先渊源，再同屏清初两方式，再合并近代形成与民国发展，最后创新保护；避免把并列方式画成时间步骤。')
compare('C03',[7,8],[own(7,8)],'乐器—曲种组合与说唱—叙事抒情是两套不同关系；合并至少并置三组器物与两组分工，超出短要点样例的教学焦点，保留各一页。')
compare('C04',[9],[[span(11,end_before='比如山东大鼓')],[span(11,begin='比如山东大鼓')]],'把题材总述和作品例证拆成两页会切断作品—价值映射；四作品样例能承载当前三组短映射，故同页。')
compare('C05',[10,11,12],[own(10,11),own(12)],'两页南北分组会把北方概括、京韵例子和西河大书小书内部对照塞入同页；三页使地域条件、同曲种内部分类、南方两例各有明确任务。南北共同原因在首张讲清，后两张作连续展开。')
compare('C06',[13,14],[own(13,14)],'京韵全段若一页须同时承载身份形成、乐器姿态、唱腔句式、两作品和三流派；拆成身份形成与艺术特点两页，后页通过曲种名回指，不复制前页正文。')
compare('C07',[15],[[span(15,end_before='伴奏乐器有')],[span(15,begin='伴奏乐器有')]],'西河仅一部作品、无流派展开，名称地域与改革均可短语呈现；机械拆两页将使来源页信息过少，且重复曲种身份。保留一页，但不增加大书小书重复内容。')
compare('C08',[16,17],[own(16,17)],'温州有三别称、限定起源、单档多任务、唱腔派别、三作品及长篇特性；一页将把身份表演与曲目实例互相挤压，拆成两页。作品页不再按每部曲拆，避免无证据补充剧情。')
compare('C09',[18,19],[own(18,19)],'三曲种同页需承载不对称身份字段、地域、唱腔、器物及六部作品，R02三乐器组只证明短标注，不证明如此多字段。选择山东一页、京东安徽同级两例一页；两例可用R29的短属性结构承载。')

